package com.mealflex.campaign.controller;
import com.mealflex.campaign.dto.*; import com.mealflex.campaign.service.CampaignService; import com.mealflex.security.UserPrincipal; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/v1/seller/stores/{storeId}/campaigns") @RequiredArgsConstructor public class SellerCampaignController {private final CampaignService service;@GetMapping public List<CampaignResponse> list(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long storeId){return service.list(p.getId(),storeId);}@PostMapping public ResponseEntity<CampaignResponse> create(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long storeId,@RequestBody CampaignRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(p.getId(),storeId,r));}@PatchMapping("/{id}/active") public ResponseEntity<Void> active(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long storeId,@PathVariable Long id,@RequestParam boolean active){service.setActive(p.getId(),storeId,id,active);return ResponseEntity.noContent().build();}}
